/* crosswalk cards, r36. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36a"]=[{"q": "A function S from the window W to the reals with S(λ) ≥ 0 at every λ. What is it called?", "a": "a spectrum", "w": ["a colour", "a curve of hue", "a triple"], "why": "A spectrum is the whole function: an amount at every wavelength."}, {"q": "A spectrum is 0 everywhere outside a reach of 0.001 around 520 nm. What is it?", "a": "a spike at 520", "w": ["a spread", "a peak", "a metamer"], "why": "Zero outside a small reach of one wavelength is a spike."}, {"q": "A spectrum is a hill as wide as W. What is it?", "a": "a spread", "w": ["a spike", "a colour", "a peak"], "why": "It is not 0 outside a small reach of any one wavelength."}, {"q": "Where a spectrum is greatest. What is that called?", "a": "its peak", "w": ["its spike", "its colour", "its spread"], "why": "The spectrum-peak technique gives a greatest value on the closed window."}, {"q": "A line reads “some λ* has S(λ*) ≥ S(λ) for every λ”, from S continuous on the closed W. Which technique licenses it?", "a": "the spectrum-peak technique", "w": ["the sum-of-spectra technique", "the three-numbers technique", "the metamer technique"], "why": "It is 12c3’s highest-and-lowest technique, run on a spectrum."}, {"q": "S is a spike at 450 and T a spike at 650. What is S + T?", "a": "a spread with two peaks", "w": ["a spike at 550", "a spike at 450", "a spread with no peak"], "why": "Two spikes far apart, added, are not 0 outside one small reach."}, {"q": "A line reads S + T = T + S for spectra. Which technique licenses it?", "a": "the sum-of-spectra technique", "w": ["the spectrum-peak technique", "the energy-weighting technique", "the mix technique"], "why": "5d1’s twelve techniques, at each λ."}, {"q": "Is a function with S(500) = −0.2 a spectrum?", "a": "no: an amount of light is never negative", "w": ["yes: any function on W is", "yes, if its peak is positive", "no: a spectrum must be a spike"], "why": "A spectrum has S(λ) ≥ 0 for every λ in W."}, {"q": "“The spectrum of this lamp is yellow.” What has gone wrong?", "a": "a spectrum is a function, not a colour", "w": ["yellow is not a wavelength", "a lamp has no spectrum", "nothing: it is a spread"], "why": "Colour comes from three numbers of the spectrum, from 36b on."}, {"q": "Two spectra both peak at 580 at the same height. Are they the same spectrum?", "a": "not necessarily", "w": ["yes, always", "yes, if both are spreads", "no, never"], "why": "9a: the same function needs the same value at every λ."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36b"]=[{"q": "The closed interval from 380 to 700 nanometres. What is it called on this rung?", "a": "the window", "w": ["the band", "the spectrum", "the gamut"], "why": "The band is the whole family; the window is the part an eye uses."}, {"q": "Radio waves, warmth, the window and the rays that burn skin, all on one line. What does the rung call the whole line?", "a": "the band", "w": ["the window", "the spectrum", "the loop"], "why": "The ladder keeps “spectrum” for 36a’s function."}, {"q": "A photon at 400 nm against one at 600 nm. How many times the energy does the first carry?", "a": "1.5", "w": ["0.67", "2", "1.25"], "why": "E(λ) = hc/λ, so the ratio is 600/400."}, {"q": "l = area of S·L over W. What is l?", "a": "one of the three numbers of S", "w": ["the energy of S", "the brightness of S", "the peak of S"], "why": "Each of the three numbers is a coefficient against one curve."}, {"q": "A line reads col(S + T) = col(S) + col(T). Which technique licenses it?", "a": "the three-numbers technique", "w": ["the energy-weighting technique", "the sum-of-spectra technique", "the two-weightings technique"], "why": "Areas add (15e1), with each curve a fixed multiplier."}, {"q": "The operator that takes a spectrum to its triple (l, m, s). What is it written?", "a": "col", "w": ["E", "bend", "cyl"], "why": "col is a function from spectra to triples."}, {"q": "A spike at 445 nm feeds which curve most?", "a": "the short curve S̃", "w": ["the long curve L", "the medium curve M", "L and M equally"], "why": "Its triple is close to (0, 0.1, 1)."}, {"q": "The coefficient of a spectrum against L + M. What is it called?", "a": "its brightness", "w": ["its energy", "its saturation", "its hue"], "why": "Its accepted name is luminance."}, {"q": "A spike at 400 nm has more energy than one at 555 nm and less brightness. Which technique says such spectra exist?", "a": "the two-weightings technique", "w": ["the three-numbers technique", "the energy-weighting technique", "the spectrum-peak technique"], "why": "Energy weights by E; the eye weights by L + M."}, {"q": "Can a spectrum’s energy be read off its three numbers?", "a": "no: col throws the weighting E away", "w": ["yes: add the three", "yes: it is l + m", "only for spikes"], "why": "Two weightings of one spectrum; three numbers do not fix the other."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36c"]=[{"q": "col(S) = col(T) for two different spectra. What are S and T?", "a": "metamers", "w": ["purples", "spikes", "mixes"], "why": "S ≈ T exactly when they share a triple."}, {"q": "What kind of relation is ≈ on spectra?", "a": "a sameness relation", "w": ["an order", "a function", "a union"], "why": "Reflexive, symmetric and transitive, since = on triples is (2h14)."}, {"q": "Every colour of some spectrum is the colour of endlessly many. Which technique says so?", "a": "the metamer technique", "w": ["the mix technique", "the purple technique", "the three-numbers technique"], "why": "S + kD ≈ S for every k ≥ 0, with col(D) = (0, 0, 0)."}, {"q": "A red light and a green light are shone together. What is the colour of the two together?", "a": "the sum of their triples", "w": ["the average of their triples", "the larger of the two", "the product of their triples"], "why": "From here on, the mix of c and d is c + d."}, {"q": "c = (1, 0.9, 0), d = (0, 0.1, 1). What is the mix of c and d?", "a": "(1, 1, 1)", "w": ["(0.5, 0.5, 0.5)", "(0, 0.09, 0)", "(1, 0.9, 1)"], "why": "A mix adds the triples, coordinate by coordinate."}, {"q": "The colours on the segment between col(380) and col(700), ends left out. What are they called?", "a": "the purples", "w": ["the greys", "the metamers", "the hues"], "why": "They are mixes of the two ends of W."}, {"q": "Can a laser, tuned to any one wavelength, make magenta?", "a": "no: no purple is the colour of a spike", "w": ["yes, near 700 nm", "yes, near 380 nm", "only at full brightness"], "why": "The purple technique, from the bow of the curve of spikes."}, {"q": "“Yellow light is red light plus green light”, said as sameness. What is wrong?", "a": "they are metamers, not the same function", "w": ["red plus green is white", "yellow is not a mix", "nothing"], "why": "The triples agree; the spectra do not."}, {"q": "“Purple is between red and violet in the rainbow.” What is wrong?", "a": "purple is on the chord, which the rainbow never touches", "w": ["purple is past violet", "purple is a spike", "the rainbow has no red"], "why": "The rainbow is the open curve of spikes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36d"]=[{"q": "A one-to-one onto function from the loop of 36c3 to the unit circle, purple at 0. What is it called?", "a": "bend", "w": ["col", "cyl", "flip"], "why": "Laid down as a choice; any one-to-one onto function would do."}, {"q": "What is hue 370°?", "a": "hue 10°", "w": ["hue 370°, a new hue", "hue 190°", "no hue"], "why": "Angles wrap: h(θ + 2π) = h(θ)."}, {"q": "h(θ) = (cos θ, sin θ). What is h(θ + 2π)?", "a": "h(θ)", "w": ["−h(θ)", "h(2θ)", "(0, 0)"], "why": "The hue-wraps technique."}, {"q": "turn_α(θ) = θ + α. What is it called?", "a": "the hue shift by α", "w": ["the opposite hue", "the flip", "the mix"], "why": "Every hue moved round by the same angle."}, {"q": "A line reads turn_α after turn_β is turn_{α+β}. Which technique licenses it?", "a": "the hue-shift technique", "w": ["the opposite technique", "the hue-chord technique", "the hue-bend technique"], "why": "21d2: turning adds arcs."}, {"q": "opp(θ) = θ + π. What is h(opp(θ))?", "a": "−h(θ)", "w": ["h(θ)", "(0, 0)", "h(2θ)"], "why": "cos(θ + π) = −cos θ and the same for sin (21e4)."}, {"q": "Hues 60° and 120° are mixed at equal strength. How far from the centre is the mix?", "a": "cos 30°, about 0.87", "w": ["1", "0.5", "0"], "why": "The hue-chord technique: |cos((θ − φ)/2)|."}, {"q": "A hue is mixed with its opposite at equal strength. Where is the mix?", "a": "at the centre", "w": ["on the circle at the first hue", "on the circle at the opposite", "outside the circle"], "why": "cos(π/2) = 0."}, {"q": "Is the mix of two different hues a hue?", "a": "no: it lies inside the circle", "w": ["yes: halfway between them", "yes, if they are near", "only at the centre"], "why": "The hue-chord technique: the circle is not closed under mixing."}, {"q": "Shifting hues by adding to the triples. What has gone wrong?", "a": "adding triples is mixing; a shift is a turn", "w": ["nothing", "the shift needs a flip", "hues cannot be shifted"], "why": "A hue shift lives on the circle."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36e"]=[{"q": "A point of the disc is r·h(θ). What is r called on this rung?", "a": "its saturation", "w": ["its hue", "its alpha", "its brightness"], "why": "Distance from the centre is saturation."}, {"q": "A colour in the cylinder is (r, θ, z). What is z?", "a": "its alpha, the brightness", "w": ["its transparency", "its saturation", "its hue"], "why": "On this rung alpha is brightness in [0, 1]."}, {"q": "Which points (x, y, z) of ℝ³ are the colours in the cylinder?", "a": "x² + y² ≤ 1 and 0 ≤ z ≤ 1", "w": ["x² + y² = 1 and 0 ≤ z ≤ 1", "x, y, a all in [0, 1]", "x² + y² + z² ≤ 1"], "why": "The cylinder technique: the disc times [0, 1]."}, {"q": "(0, 30°, ½) and (0, 200°, ½). Are they one colour?", "a": "yes: at r = 0 any θ names the same grey", "w": ["no: their hues differ", "no: one is brighter", "yes: their hues are opposite"], "why": "The grey-axis technique compares θ only when r > 0."}, {"q": "At a grey the angle is read from y/x. What is it there?", "a": "0/0, which has no value", "w": ["0", "1", "π"], "why": "5e5: no number times zero is one."}, {"q": "Every colour with z = 0. What is it?", "a": "black", "w": ["a dark hue", "grey", "white"], "why": "The ends technique: no light gives (0, 0, 0)."}, {"q": "(1, θ, 0) for a fully saturated θ. What colour is it?", "a": "black", "w": ["the hue θ, dim", "grey", "no colour"], "why": "The ends technique: every colour with z = 0 is black."}, {"q": "Which chart makes mixing two lights an addition?", "a": "the triples (l, m, s)", "w": ["the cylinder (r, θ, z)", "neither", "both alike"], "why": "Mixing is addition in (l, m, s), a chord in the cylinder."}, {"q": "Which chart makes a hue shift a turn?", "a": "the cylinder (r, θ, z)", "w": ["the triples (l, m, s)", "neither", "both alike"], "why": "A hue shift adds to θ."}, {"q": "Hue 350° and hue 10° at r = 1 are averaged coordinate by coordinate. What is wrong?", "a": "averaging angles fails across 0", "w": ["nothing", "saturation must be averaged first", "the cylinder has no 350°"], "why": "The true mix sits near hue 0, not 180°."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36f"]=[{"q": "The set of all triples col(S) for spectra S on W. What is it called?", "a": "the eye’s region G", "w": ["the gamut", "the gamut triangle", "the window"], "why": "Drawn at fixed brightness, it is a horseshoe."}, {"q": "The colour halfway between two colours the eye can see. Is it in G?", "a": "yes: G is convex", "w": ["no: it may be a purple", "only if both are spikes", "only at fixed brightness"], "why": "k·c + (1 − k)·d = col(kS + (1 − k)T)."}, {"q": "All mixes u·p + v·q + w·r with u, v, w ≥ 0 and u + v + w = 1. What is it?", "a": "the gamut triangle", "w": ["the gamut", "the eye’s region", "the purples"], "why": "Without u + v + w = 1 it is the whole gamut."}, {"q": "A line reads “the gamut triangle lies inside G”. Which technique licenses it?", "a": "the gamut technique", "w": ["the convexity technique", "the straight-edge technique", "the chart technique"], "why": "A mix of mixes is a mix, and G is convex and holds p, q, r."}, {"q": "The only straight part of G’s boundary. What is it?", "a": "the purples", "w": ["the greens", "the greys", "the curve of spikes"], "why": "The straight-edge technique: it is a chord."}, {"q": "The point of the gamut triangle nearest to a colour c outside it. What is it called?", "a": "the gamut name of c", "w": ["the gamut of c", "the hue of c", "the purple of c"], "why": "Found as 13·stat’s least-squares point."}, {"q": "A colour outside the gamut and its gamut name. Which way does the error point?", "a": "outward, toward saturation", "w": ["inward, toward grey", "toward black", "in no known direction"], "why": "The missed colour is more saturated than its name."}, {"q": "A colour outside the gamut is clamped coordinate by coordinate. What can go wrong?", "a": "its hue can change", "w": ["nothing", "it leaves G", "it becomes grey"], "why": "The nearest point keeps the hue; clamping may not."}, {"q": "Three primaries chosen on one line through (0, 0, 0). What do they reach?", "a": "no triangle, and no gamut", "w": ["the whole of G", "the purples", "a horseshoe"], "why": "The gamut needs three colours not on one line."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36g"]=[{"q": "A patch, a word or a triple, standing for a colour. What is each called?", "a": "a colour name", "w": ["a colour fact by cases", "a spectrum", "a metamer"], "why": "None of the three is the thing; each names it."}, {"q": "On the matter of light, when are two colour names the same?", "a": "exactly when their triples are", "w": ["exactly when their words are", "when their spectra are equal", "never"], "why": "The name technique."}, {"q": "“The patch on the wall is 🟦.” Is the patch used or mentioned?", "a": "mentioned", "w": ["used", "neither", "both"], "why": "The statement is about the patch itself (0a9)."}, {"q": "S ∈ c. What does it say?", "a": "col(S) is c’s triple", "w": ["S is part of c", "S is the colour c", "c is a spectrum"], "why": "A spectrum is in the colour, not part of it (2d12)."}, {"q": "Are red ∪ green and red + green the same set?", "a": "no: the union holds two triples, the mix one", "w": ["yes, always", "yes, for lights", "only for pigments"], "why": "The set technique."}, {"q": "“This solvent darkens this family of pigments”, held at the rate the jars give. What is it?", "a": "a colour fact by cases", "w": ["a technique", "an axiom", "a colour name"], "why": "It carries its rate, the spread of the cases."}, {"q": "A fact by cases enters a column as a line. What goes with it?", "a": "its rate", "w": ["its proof", "its triple", "nothing"], "why": "The cases technique carries the rate forward."}, {"q": "A statement about all colours is proved for l, m and s and joined with and. Which technique licenses the join?", "a": "the component technique", "w": ["the cases technique", "the name technique", "the set technique"], "why": "2h5’s equal pairs, and 1c2’s join."}, {"q": "A rate is dropped from a fact by cases to make the line look exact. What has happened?", "a": "sizes have been crossed", "w": ["a technique has been proved", "the line is now an axiom", "nothing"], "why": "A fact by cases is true at the size of a crowd."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36h"]=[{"q": "c·d, each coordinate the product. What is it called?", "a": "the pigment mix", "w": ["the light mix", "screen", "darken"], "why": "One material through the other: transmission."}, {"q": "c = (1, 1, 0) and d = (0, 1, 1). What is their light mix?", "a": "(1, 1, 1)", "w": ["(0, 1, 0)", "(1, 2, 1)", "(0.5, 1, 0.5)"], "why": "c + d, clamped at 1."}, {"q": "c = (1, 1, 0) and d = (0, 1, 1). What is their pigment mix?", "a": "(0, 1, 0)", "w": ["(1, 1, 1)", "(1, 2, 1)", "(0.5, 1, 0.5)"], "why": "Each coordinate the product."}, {"q": "clamp(c + d − 1), each coordinate. What is it called?", "a": "burn", "w": ["dodge", "screen", "difference"], "why": "Dodge shifted down by one."}, {"q": "A line reads burn(c, d) = inv(dodge(inv c, inv d)). Which technique licenses it?", "a": "the dodge–burn technique", "w": ["the screen technique", "the corners technique", "the lattice technique"], "why": "1 − clamp(2 − t) = clamp(t − 1) for every t."}, {"q": "1 − (1 − c)(1 − d), each coordinate. What is it called?", "a": "screen", "w": ["burn", "lighten", "the light mix"], "why": "The pigment mix done on the inverts and inverted back."}, {"q": "c = (0.9, 0.2, 0.5) and d = (0.4, 0.6, 0.5). What is darken(c, d)?", "a": "(0.4, 0.2, 0.5)", "w": ["(0.9, 0.6, 0.5)", "(0.5, 0.4, 0)", "(0.36, 0.12, 0.25)"], "why": "The lesser in each coordinate."}, {"q": "On the corners 0 and 1, which of 1e’s tables is difference?", "a": "or-but-not-both", "w": ["and", "or", "not"], "why": "|0 − 1| = 1 and |1 − 1| = 0."}, {"q": "Pigment mix and darken at (½, ½). What do they give?", "a": "¼ and ½", "w": ["½ and ½", "¼ and ¼", "1 and ½"], "why": "They agree at the corners and not between."}, {"q": "lighten(x, inv x) at x = ½. What is it, and what fails there?", "a": "½: the either-way principle fails", "w": ["1: nothing fails", "0: pushing a not fails", "½: nothing fails"], "why": "max(x, 1 − x) is 1 only at the corners."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36i"]=[{"q": "(c, d), with c at one place and d at the next. What is it?", "a": "a pair of colours, side by side", "w": ["the mix of c and d", "a metamer", "a colour"], "why": "2h1’s ordered pair, as a picture."}, {"q": "A flag with red over green and one with green over red. Are they the same picture?", "a": "no: (c, d) ≠ (d, c) unless c = d", "w": ["yes: same colours", "yes: same mix", "only from far away"], "why": "The pair technique."}, {"q": "A flag with red over green and one with green over red. Are their mixes the same?", "a": "yes", "w": ["no", "only if red = green", "only for pigments"], "why": "mix(c, d) = mix(d, c)."}, {"q": "mix(c, d) = mix(d, c) with (c, d) ≠ (d, c). What does it show?", "a": "the mix function is not one-to-one", "w": ["the pair function is not one-to-one", "the mix is a pair", "c = d"], "why": "The mix-forgetting technique."}, {"q": "The distance at which the eye stops telling two places apart. What kind of statement gives it?", "a": "a fact by cases, with a rate", "w": ["a technique", "an axiom", "a definition"], "why": "Resolution is laid down as measured."}, {"q": "k·mix(c, d)/2 + (1 − k)·(the pair), for k in [0, 1]. What is it called?", "a": "the seen mix", "w": ["the light mix", "the pigment mix", "the pair"], "why": "A gradient from the pair to the mix."}, {"q": "At k = 0, what does the seen mix give?", "a": "the pair", "w": ["the mix", "grey", "black"], "why": "At k = 1 it gives the mix."}, {"q": "“xy” and “x ∧ y”. Which is like red beside green?", "a": "“xy”", "w": ["“x ∧ y”", "both", "neither"], "why": "Juxtaposition; yellow is the joined statement."}, {"q": "A colour is given. Can the pair it came from be read off it?", "a": "no", "w": ["yes, by subtracting", "yes, if it is yellow", "only for metamers"], "why": "The mix-forgetting technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["36j"]=[{"q": "The three curves were drawn by matching many observers. What is each curve, in 30’s words?", "a": "a most likely parameter with its width", "w": ["an axiom", "a technique", "a bias"], "why": "30r’s fit with 30q’s width."}, {"q": "The error of a gamut name. What is special about its direction?", "a": "it is known before the fit: outward", "w": ["it is random", "it points inward", "it is always zero"], "why": "36f4."}, {"q": "The three numbers of a spectrum, in 31’s words. What are they?", "a": "its dot products with the three curves", "w": ["its three peaks", "its lengths", "its three angles"], "why": "A coefficient is a total of a product."}, {"q": "Two spectra differ only in a direction at right angles to all three curves. What are they?", "a": "metamers", "w": ["purples", "spikes", "opposites"], "why": "col reads three directions and drops the rest."}, {"q": "A hue shift, in 32’s words. What is it?", "a": "a shift of phase", "w": ["a new coefficient", "a turning added", "a convolution"], "why": "A function of hue is periodic in θ."}, {"q": "A dye spreading in still water, each colour coordinate for temperature. Which equation?", "a": "the heat equation", "w": ["the wave equation", "the turning sum", "no equation"], "why": "36j4."}, {"q": "The cylinder with its ends pinched. In 34’s words, what is it?", "a": "a closed surface of another kind", "w": ["a closed curve", "a disc", "a convex region"], "why": "36e4 and 36j5."}, {"q": "How many spectra does one colour have?", "a": "uncountably many", "w": ["three", "countably many", "one"], "why": "One for every real k, and the reals are 35’s larger size."}, {"q": "Two spectra land on one triple. Are their energies still different, if they were?", "a": "yes", "w": ["no: one triple, one energy", "only for spikes", "only before col"], "why": "The reduction technique: a function does not alter its inputs."}, {"q": "Every statement true of a spectrum before col is applied is true after. Which technique?", "a": "the reduction technique", "w": ["the metamer technique", "the mix-forgetting technique", "the three-numbers technique"], "why": "col is a function; the spectrum is the same object."}];
